from collections import Counter


def transform(grid):
    """Recolor the trailing background portion of a left-anchored horizontal stripe."""
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        if row[0] == background:
            continue
        i = 0
        while i < len(row) and row[i] != background:
            i += 1
        if 0 < i < len(row) and all(v == background for v in row[i:]):
            out[r][i:] = [1] * (len(row) - i)
    return out

